/* PROTOTIPO EN RAMA: ficha unificada cliente → orden → artículos.
   Solo lectura. No modifica R2, pagos, biblioteca, permisos ni datos. */
import { state } from '../state.js';
import * as storageManager from '../storage-manager.js';
import { fmtDate, fmtMoney } from '../ui.js';
import { escHtml, escAttr } from '../sanitize.js';

const TAB_ID = 'ficha-unificada';
let renderToken = 0;
function norm(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
function clienteById(id){return (state.clientes||[]).find(c=>c.id===id)||{};}
function itemsOrden(id){return (state.ordenItems||[]).filter(it=>it.ordenId===id).sort((a,b)=>Number(a.numeroItem||0)-Number(b.numeroItem||0));}
function agregarFotos(dest,origen,categoriaFallback=null){if(!origen)return;if(Array.isArray(origen)){origen.forEach(f=>{if(!f)return;dest.push(typeof f==='string'?{url:f,categoria:categoriaFallback||undefined}:{...f,categoria:f.categoria||categoriaFallback||undefined});});return;}if(typeof origen==='object')Object.entries(origen).forEach(([categoria,lista])=>{if(Array.isArray(lista))agregarFotos(dest,lista,categoria);});}
function fotosOrden(o){const res=[],vistos=new Set();let nodo=o;while(nodo&&typeof nodo==='object'&&!Array.isArray(nodo)&&!vistos.has(nodo)){vistos.add(nodo);agregarFotos(res,nodo.fotos);nodo=nodo.extra&&typeof nodo.extra==='object'&&!Array.isArray(nodo.extra)?nodo.extra:null;}const keys=new Set();return res.filter(f=>{const k=f.path||f.url||JSON.stringify(f);if(!k||keys.has(k))return false;keys.add(k);return true;});}
function fotosItem(o,it,totalItems){const todas=fotosOrden(o);const ligadas=todas.filter(f=>f&&(f.itemId===it.id||f.item===it.codigo));if(ligadas.length)return ligadas;if(totalItems===1)return todas.filter(f=>f&&!f.itemId&&!f.item);return [];}
function registroServicio(it,nombre){const obj=it.registroServicios&&typeof it.registroServicios==='object'?it.registroServicios:{};if(obj[nombre])return true;return(state.registroPares||[]).some(r=>r.codigo===it.codigo&&r.servicio===nombre);}
function estadoRank(estado){return({'Recibido y registrado':0,'Lavado':1,'Secado y detallado':2,'Pintado y personalizado':3,'Control de calidad':4,'Biblioteca':5,'Entregado':6})[estado]??0;}
function resumenProceso(it){const rank=estadoRank(it.estado);return{lavado:registroServicio(it,'Lavado')||rank>=1,detallado:registroServicio(it,'Secado y detallado')||rank>=2};}
function buscar(qRaw){const q=norm(qRaw);if(!q)return[];const ordenes=(state.ordenes||[]).filter(o=>o&&o.eliminada!==true);if(/^\d+$/.test(q)){const n=Number(q);return ordenes.filter(o=>Number(o.numero)===n);}if(/^\d+\s*-\s*\d+$/.test(q)){const codigo=q.replace(/\s/g,'');const ids=new Set((state.ordenItems||[]).filter(it=>norm(it.codigo)===codigo).map(it=>it.ordenId));return ordenes.filter(o=>ids.has(o.id));}return ordenes.filter(o=>{const c=clienteById(o.clienteId);const camposOrden=[c.nombre,c.telefono,c.whatsapp,o.numero,o.observaciones].map(norm);if(camposOrden.some(v=>v.includes(q)))return true;return itemsOrden(o.id).some(it=>[it.codigo,it.descripcion,it.marca,it.modelo,it.talla,it.color].map(norm).some(v=>v.includes(q)));}).sort((a,b)=>Number(b.numero||0)-Number(a.numero||0));}
function chip(texto,ok,neutral=false){const cls=neutral?'neutral':(ok?'ok':'pend');return'<span class="sm-fu-chip '+cls+'">'+escHtml(texto)+'</span>';}
function htmlOrden(o){const c=clienteById(o.clienteId),items=itemsOrden(o.id),total=Number(o.precio||0)-Number(o.descuento||0),pagado=Number(o.pagado||0),pagoOk=o.estadoPago==='Pagado'||pagado>=total;return'<article class="sm-fu-order" data-order-id="'+escAttr(o.id)+'"><div class="sm-fu-order-head"><div><div class="sm-fu-kicker">ORDEN #'+escHtml(o.numero)+'</div><h2>'+escHtml(c.nombre||'Cliente sin nombre')+'</h2><div class="hint">Ingreso '+escHtml(fmtDate(o.fechaIngreso))+' · Entrega estimada '+escHtml(fmtDate(o.fechaEstimada))+'</div></div><div class="sm-fu-summary">'+chip(pagoOk?'✓ Pagado':'💰 Pago pendiente',pagoOk)+chip((o.estado||'Sin estado'),true,true)+'</div></div><div class="sm-fu-money"><span>Total <strong>'+escHtml(fmtMoney(total))+'</strong></span><span>Pagado <strong>'+escHtml(fmtMoney(pagado))+'</strong></span><span>Saldo <strong>'+escHtml(fmtMoney(Math.max(total-pagado,0)))+'</strong></span></div><div class="sm-fu-items">'+items.map((it,i)=>htmlItem(o,it,items.length,i)).join('')+'</div><div class="sm-fu-actions"><button class="btn btn-ghost btn-sm" onclick="viewOrdenDetalle(\''+escAttr(o.id)+'\')">Ver detalle original</button></div></article>';}
function htmlItem(o,it,totalItems,index){const proceso=resumenProceso(it),ubic=it.biblioteca&&it.biblioteca.ubicacion?it.biblioteca.ubicacion:'',fotos=fotosItem(o,it,totalItems),fotosData=encodeURIComponent(JSON.stringify(fotos.map(f=>({url:f.url,path:f.path,itemId:f.itemId,item:f.item,categoria:f.categoria}))));return'<section class="sm-fu-item" data-item-id="'+escAttr(it.id)+'" data-fotos="'+escAttr(fotosData)+'"><div class="sm-fu-photo" id="sm-fu-photo-'+escAttr(it.id)+'"><div class="sm-fu-photo-empty">👟<small>Foto</small></div></div><div class="sm-fu-item-body"><div class="sm-fu-item-top"><div><strong class="mono">'+escHtml(it.codigo||('Artículo '+(index+1)))+'</strong><div class="sm-fu-desc">'+escHtml(it.descripcion||[it.marca,it.modelo,it.talla&&('Talla '+it.talla)].filter(Boolean).join(' · ')||'Sin descripción')+'</div></div>'+chip(it.estado||'Sin estado',true,true)+'</div><div class="sm-fu-status-grid"><div><span>🧼 Lavado</span><strong>'+(proceso.lavado?'✓ Sí':'— Pendiente')+'</strong></div><div><span>✨ Detallado</span><strong>'+(proceso.detallado?'✓ Sí':'— Pendiente')+'</strong></div><div><span>📚 Biblioteca</span><strong>'+(ubic?escHtml(ubic):'No ubicado')+'</strong></div><div><span>📦 Estado actual</span><strong>'+escHtml(it.estado||'Sin estado')+'</strong></div></div></div></section>';}
async function cargarFotos(token){const cards=Array.from(document.querySelectorAll('#sm-fu-results .sm-fu-item'));for(const card of cards){if(token!==renderToken)return;let fotos=[];try{fotos=JSON.parse(decodeURIComponent(card.dataset.fotos||'[]'));}catch(_){}if(!fotos.length)continue;let resolved=[];try{resolved=await storageManager.resolveImageUrls(fotos);}catch(_){}if(token!==renderToken)return;const valid=resolved.filter(f=>f&&f.resolvedUrl&&!String(f.resolvedUrl).startsWith('r2://'));if(!valid.length)continue;const box=card.querySelector('.sm-fu-photo');if(!box)continue;const first=valid[0];box.innerHTML='<img src="'+escAttr(first.resolvedUrl)+'" alt="Foto del artículo" loading="lazy">'+(valid.length>1?'<span class="sm-fu-more">+'+(valid.length-1)+'</span>':'');}}
export function renderFichaUnificada(q=null){const input=document.getElementById('sm-fu-search'),texto=q!==null?q:(input?input.value:'');if(input&&q!==null)input.value=q;const out=document.getElementById('sm-fu-results');if(!out)return;const token=++renderToken,resultados=buscar(texto);if(!norm(texto)){out.innerHTML='<div class="sm-fu-empty"><div>🔎</div><strong>Busca una orden, cliente o artículo</strong><span>Ejemplo: 70, 70-1, nombre del cliente, marca o modelo.</span></div>';return;}if(!resultados.length){out.innerHTML='<div class="sm-fu-empty"><div>∅</div><strong>No encontramos resultados</strong><span>Si buscaste un número de orden, la búsqueda es exacta.</span></div>';return;}out.innerHTML='<div class="sm-fu-count">'+resultados.length+(resultados.length===1?' orden encontrada':' órdenes encontradas')+'</div>'+resultados.map(htmlOrden).join('');cargarFotos(token);}
export function abrirFichaUnificada(){document.querySelectorAll('.tab-section').forEach(s=>s.classList.remove('active'));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===TAB_ID));document.getElementById('tab-'+TAB_ID)?.classList.add('active');if(typeof window.closeMobileMenu==='function')window.closeMobileMenu();const input=document.getElementById('sm-fu-search');setTimeout(()=>input?.focus(),0);}
function instalarUI(){if(document.getElementById('tab-'+TAB_ID))return;const refTab=document.getElementById('tab-ordenes');if(!refTab||!refTab.parentElement)return;const style=document.createElement('style');style.id='sm-fu-style';style.textContent=`.sm-fu-wrap{max-width:1180px;margin:0 auto}.sm-fu-hero{padding:18px;border:1px solid var(--line);border-radius:14px;background:var(--surface,#fff);margin-bottom:14px}.sm-fu-hero h1{margin:0 0 4px}.sm-fu-searchbar{display:flex;gap:8px;margin-top:14px}.sm-fu-searchbar input{flex:1;min-width:0;font-size:16px;padding:12px}.sm-fu-count{font-size:12px;color:var(--ink-soft);margin:8px 2px}.sm-fu-order{border:1px solid var(--line);border-radius:14px;background:var(--surface,#fff);padding:14px;margin:0 0 14px;box-shadow:0 2px 8px rgba(0,0,0,.03)}.sm-fu-order-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.sm-fu-order-head h2{margin:2px 0 4px;font-size:20px}.sm-fu-kicker{font-size:12px;font-weight:800;letter-spacing:.08em;color:var(--red)}.sm-fu-summary,.sm-fu-actions{display:flex;gap:6px;flex-wrap:wrap}.sm-fu-chip{display:inline-flex;align-items:center;border-radius:999px;padding:5px 9px;font-size:12px;font-weight:700}.sm-fu-chip.ok{background:#eaf8ef;color:#166534}.sm-fu-chip.pend{background:#fff3e7;color:#9a3412}.sm-fu-chip.neutral{background:var(--bg-soft,#f3f4f6);color:var(--ink)}.sm-fu-money{display:flex;gap:18px;flex-wrap:wrap;padding:10px 0;margin-top:8px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:13px}.sm-fu-item{display:grid;grid-template-columns:112px 1fr;gap:13px;padding:13px 0;border-bottom:1px solid var(--line)}.sm-fu-item:last-child{border-bottom:0}.sm-fu-photo{width:112px;height:112px;border-radius:10px;overflow:hidden;background:var(--bg-soft,#f3f4f6);position:relative}.sm-fu-photo img{width:100%;height:100%;object-fit:cover}.sm-fu-photo-empty{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:28px;color:var(--ink-soft)}.sm-fu-photo-empty small{font-size:11px}.sm-fu-more{position:absolute;right:5px;bottom:5px;background:rgba(0,0,0,.72);color:#fff;border-radius:999px;padding:3px 7px;font-size:11px}.sm-fu-item-top{display:flex;justify-content:space-between;gap:8px}.sm-fu-desc{margin-top:4px;color:var(--ink-soft);font-size:13px}.sm-fu-status-grid{display:grid;grid-template-columns:repeat(4,minmax(110px,1fr));gap:8px;margin-top:12px}.sm-fu-status-grid>div{border:1px solid var(--line);border-radius:9px;padding:8px}.sm-fu-status-grid span,.sm-fu-status-grid strong{display:block;font-size:12px}.sm-fu-status-grid strong{margin-top:3px}.sm-fu-actions{justify-content:flex-end;margin-top:10px}.sm-fu-empty{text-align:center;padding:48px 16px;color:var(--ink-soft);display:flex;flex-direction:column;gap:5px}.sm-fu-empty>div{font-size:34px}.sm-fu-proto{font-size:10px;margin-left:5px;padding:2px 5px;border-radius:999px;background:#fff3cd;color:#7a5600}@media(max-width:720px){.sm-fu-order-head{flex-direction:column}.sm-fu-item{grid-template-columns:82px 1fr}.sm-fu-photo{width:82px;height:82px}.sm-fu-status-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sm-fu-searchbar{flex-direction:column}}`;document.head.appendChild(style);const sec=document.createElement('div');sec.className='tab-section';sec.id='tab-'+TAB_ID;sec.innerHTML='<div class="sm-fu-wrap"><div class="sm-fu-hero"><div class="sm-fu-kicker">PROTOTIPO · RAMA DE PRUEBA</div><h1>Consulta unificada</h1><div class="page-sub">Cliente, orden, artículo, foto, proceso, pago y ubicación de biblioteca en una sola pantalla.</div><div class="sm-fu-searchbar"><input id="sm-fu-search" placeholder="N.º exacto de orden, cliente, precinto, marca o modelo" autocomplete="off"><button class="btn btn-primary" id="sm-fu-btn">Buscar</button><button class="btn btn-ghost" id="sm-fu-clear">Limpiar</button></div><div class="hint" style="margin-top:8px">N.º de orden es exacto: buscar 70 muestra únicamente la orden 70.</div></div><div id="sm-fu-results"></div></div>';refTab.parentElement.insertBefore(sec,refTab);sec.querySelector('#sm-fu-btn').onclick=()=>renderFichaUnificada();sec.querySelector('#sm-fu-clear').onclick=()=>{const i=sec.querySelector('#sm-fu-search');if(i)i.value='';renderFichaUnificada('');};sec.querySelector('#sm-fu-search').onkeydown=e=>{if(e.key==='Enter')renderFichaUnificada();};const ordenBtn=document.querySelector('.nav-item[data-tab="ordenes"]');if(ordenBtn&&ordenBtn.parentElement){const btn=document.createElement('button');btn.className='nav-item';btn.dataset.tab=TAB_ID;btn.innerHTML='<span class="ic">🔎</span>Consulta <span class="sm-fu-proto">PRUEBA</span>';btn.onclick=abrirFichaUnificada;ordenBtn.insertAdjacentElement('afterend',btn);}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',instalarUI,{once:true});else instalarUI();
Object.assign(window,{abrirFichaUnificada,renderFichaUnificada});
